/* ---------- JIRA ----------
   Campos:
     ticket   : identificador do chamado no Jira (ex: SAC-4892)
     titulo   : resumo do chamado
     tipo     : Tipo de item
     cliente  : nome do laboratório / cliente
     status   : Status atual
     criado   : Data de criação  "dd/mm/aaaa hh:mm"
     limite   : Data limite      "dd/mm/aaaa hh:mm" ou ""
     classe   : Classificação Comercial (A / B / C)
   ========================================================= */

function _extrairClienteJira(titulo) {
  const m = titulo.match(/^([^-–]+?)\s*[-–]/);
  return m ? m[1].trim() : titulo.split(' ')[0];
}

function _calcTempoJira(criado, limite) {
  if (!limite) return '—';
  const parse = (s, defaultTime) => {
    const p = s.trim().split(' ');
    const [d, mo, y] = p[0].split('/').map(Number);
    const [h, mi] = (p[1] || defaultTime).split(':').map(Number);
    return new Date(y, mo - 1, d, h, mi);
  };
  const dtC = parse(criado, '00:00');
  const dtL = parse(limite, '23:59');
  const diff = Math.round((dtL - dtC) / 60000);
  if (isNaN(diff) || diff < 0) return '—';
  const days = Math.floor(diff / 1440);
  const hours = Math.floor((diff % 1440) / 60);
  const mins = diff % 60;
  return days > 0 ? `${days}d ${hours}h ${mins}min` : `${hours}h ${mins}min`;
}

